//! FORM target reflects exact authored browsing-context metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://submitter-form-target-input.test/submit><input id=area name=q value=Seed><input id=charset type=hidden name=_charset_ value=author><input id=submit type=submit name=go value=sent></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://submitter-form-target-input.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn input_form_target_canonical_exact_once_conversion_and_raw_units(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('submit'),a=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'formTarget');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get formTarget'||a.set.name!=='set formTarget'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'formTarget')||x.formTarget!=='')throw 'canonical';var calls=0;x.formTarget={toString:function(){calls++;return '  UTF-8\ud800  ';},valueOf:function(){throw 'wrong hint';}};if(calls!==1||x.formTarget!=='  UTF-8\ud800  '||x.getAttributeNS(null,'formtarget')!==x.formTarget)throw 'exact raw';x.formTarget=null;if(x.formTarget!=='null')throw 'ordinary null';x.formTarget=undefined;if(x.formTarget!=='undefined')throw 'ordinary undefined';"#);}
#[test]
fn input_form_target_inert_exact_attribute_name_namespace_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml','input');x.setAttributeNS('urn:foreign','formtarget','foreign');x.setAttributeNS(null,'FORMTARGET','upper');x.setAttributeNS(null,'FormTarget','other');if(x.formTarget!=='')throw 'exact key';x.formTarget='A\ud800Z';var copy=x.cloneNode(false);copy.formTarget='copy';if(x.formTarget!=='A\ud800Z'||copy.formTarget!=='copy'||copy.getAttributeNodeNS(null,'formtarget')===x.getAttributeNodeNS(null,'formtarget')||x.getAttributeNS('urn:foreign','formtarget')!=='foreign'||x.getAttributeNS(null,'FormTarget')!=='other')throw 'independent copy';"#);}

#[test]
fn input_form_target_keywords_remain_exact_metadata(){let(mut d,mut f,mut p)=fixture();for label in ["_self","_blank","_parent","_top","_unfencedTop","NamedFrame","  _SELF  ",""]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('submit');x.formTarget='{label}';if(x.formTarget!=='{label}'||x.getAttributeNS(null,'formtarget')!=='{label}')throw 'exact target';"));}}
#[test]
fn input_form_target_resource_refusal_is_atomic_and_fresh_job_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit');x.formTarget='off';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.input_form_target_get(object).map(|_|())}else{bridge.input_form_target_set(object,&Value::String("growing-unknown-name-value".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.formTarget='ON';if(x.formTarget!=='ON'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}
#[test]
fn input_form_target_attribute_writers_observe_raw_values_and_preserve_dirty_editor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),editor=document.getElementById('area');editor.value='Edited';x.formTarget='on';var attribute=x.getAttributeNodeNS(null,'formtarget'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['formtarget']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('formtarget','OFF');","x.setAttributeNS(null,'formtarget','OFF');","attribute.value='OFF';","attribute.nodeValue='OFF';","attribute.textContent='OFF';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.formTarget='on';watch.takeRecords();");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.formTarget!=='OFF'||x.getAttributeNodeNS(null,'formtarget')!==attribute||records.length!==1||records[0].oldValue!=='on'||records[0].attributeName!=='formtarget'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('formtarget');replacement.value='off\ud800';x.setAttributeNodeNS(replacement);if(x.formTarget!=='off\ud800'||attribute.ownerElement!==null||replacement.ownerElement!==x||replacement.value!=='off\ud800')throw 'raw attribute replacement';"#);}

#[test]
fn input_form_target_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'formTarget'),calls=0;if(a.get.call(x)!=='')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-submitter-form-target-input.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'on';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://submitter-form-target-input.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'ON');if(x.formTarget!=='ON')throw 'fresh recovery';");}

#[test]
fn input_form_target_brand_abrupt_conversion_and_prototype_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('submit'),P=HTMLInputElement.prototype,a=Object.getOwnPropertyDescriptor(P,'formTarget'),calls=0;for(var bad of [{},document,document.body,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.formTarget={toString:function(){calls++;x.formTarget='inner';return ' OUTER ';}};if(calls!==1||x.formTarget!==' OUTER ')throw 'once';var marker={};try{x.formTarget={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(x.formTarget!==' OUTER '||x.getAttribute('data-side')!=='kept')throw 'abrupt';Object.defineProperty(P,'formTarget',{get:function(){return 'author';},configurable:true});a.set.call(x,'native');if(x.formTarget!=='author'||a.get.call(x)!=='native')throw 'saved authority';delete P.formTarget;if(x.formTarget!==undefined)throw 'deleted canonical';Object.defineProperty(P,'formTarget',a);var C=HTMLInputElement;delete window.HTMLInputElement;if(!(x instanceof C)||a.get.call(x)!=='native')throw 'saved constructor';"#);}


#[test]
fn input_form_target_wrong_interface_rejects_before_conversion_and_ordinary_receiver_reflects(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('submit'),a=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'formTarget'),calls=0,other=document.createElement('button');for(var bad of [other,document.getElementById('form')]){try{a.get.call(bad);throw 'getter brand';}catch(e){if(!(e instanceof TypeError))throw e;}try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});throw 'setter brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';var ordinary=document.createElement('input');ordinary.formTarget=' _BLANK ';if(ordinary.formTarget!==' _BLANK '||ordinary.getAttributeNS(null,'formtarget')!==' _BLANK ')throw 'ordinary';document.getElementById('area').setAttribute('name','formTarget');a.set.call(x);if(x.formTarget!=='undefined'||a.get.call(x)!=='undefined')throw 'canonical neighbor and missing argument';");}
